export const FACTIONS={
 ward:{name:'Вартові Вирію',npc:'faction-ward',leader:'Сотниця Зоряна',desc:'Охороняйте стежки й поверніть честь старій варті.',gift:'Знак незламної варти',bonus:{hp:60,def:5},perk:'+60 HP, +5 захисту',targets:['wolf','skeleton','castleward']},
 grove:{name:'Коло пралісу',npc:'faction-grove',leader:'Відун Лесь',desc:'Почуйте духів лісу та зупиніть спотворення природи.',gift:'Пам’ять пралісу',bonus:{sp:30,mdef:5},perk:'+30 SP, +5 магічного захисту',targets:['mushroom','thornmantis','thorndryad']},
 forge:{name:'Братство Жару',npc:'faction-forge',leader:'Майстриня Рута',desc:'Зберіть жар старих горнів і відновіть ремесло Оберегу.',gift:'Серце горна',bonus:{atk:8,matk:8},perk:'+8 атаки й магічної атаки',targets:['dragon','sunscarab','ironmole']}
};
export const REP_RANKS=[{value:0,name:'Незнайомець'},{value:100,name:'Союзник'},{value:250,name:'Довірений'},{value:500,name:'Оборонець'}];
export const factionRank=n=>REP_RANKS.filter(r=>n>=r.value).at(-1);
export const BUILDINGS={garden:{name:'Травник',material:'herb',amount:5,desc:'Кожні 5 хвилин активної гри: 3 трави за ранг і одне зілля. Зібрати можна особисто у садибі.'},workshop:{name:'Майстерня',material:'ore',amount:5,desc:'Відкриває фракційні рецепти. Вищі ранги зменшують витрати матеріалів.'},hall:{name:'Зала трофеїв',material:'embershard',amount:3,desc:'Виставляйте трофеї переможених босів. Кожен зайнятий постамент додає +15 HP; один постамент за ранг.'}};
export const buildingCost=(id,level)=>({zeny:500*(level+1)**2,material:BUILDINGS[id].material,count:BUILDINGS[id].amount*(level+1)});
export const SECRETS={
 'runes-forest':{zone:'forest',name:'Камінь трьох пір',hint:'Спершу лист народжується, потім палає сонце, останнім падає сніг.',runes:['Лист','Сонце','Сніг'],order:[0,1,2],reward:'secret-leaf'},
 'runes-crypt':{zone:'crypt',name:'Шепіт замурованої кімнати',hint:'З темряви приходить іскра. Іскра кличе дзвін. Дзвін будить світло.',runes:['Світло','Іскра','Дзвін'],order:[1,2,0],reward:'secret-bell'},
 'runes-castle':{zone:'castlecourt',name:'Клятва порожнього трону',hint:'Перед короною стояв щит. Перед щитом горіло серце.',runes:['Корона','Серце','Щит'],order:[1,2,0],reward:'secret-crown'}
};
export const isNight=clock=>clock%600>=300;
export const STAT_NAMES={atk:'Атака',matk:'Магічна атака',def:'Захист',mdef:'Магічний захист',hp:'Здоров’я',sp:'Енергія',haste:'Темп атак',interval:'Інтервал атак',STR:'Сила',AGI:'Спритність',VIT:'Витривалість',INT:'Інтелект',DEX:'Влучність',LUK:'Удача'};
export function installLivingWorld(zones,enemies,items){
 let n=0;for(const [id,f]of Object.entries(FACTIONS)){zones.village.objects.push({id:f.npc,kind:'npc',faction:id,name:f.leader,x:11+n*3,y:29,art:'acolyte',npcFrame:n*4,dialogue:f.desc+' Поговорімо про наш шлях.'});n++;for(let tier=1;tier<=3;tier++){items['faction-'+id+'-'+tier]={name:f.gift+' · '+tier,kind:'accessory',slot:'accessory',rarity:['uncommon','rare','epic'][tier-1],bound:true,price:1000*tier,requirements:{level:10*tier},stats:id==='ward'?{hp:50*tier,def:4*tier}:id==='grove'?{sp:25*tier,mdef:4*tier}:{atk:6*tier,matk:6*tier},desc:'Особиста відзнака: '+f.name};}}
 zones.village.houses.push({x:8,y:32,w:4,h:3,art:0,name:'Садиба мандрівника'});zones.village.objects.push({id:'homestead',kind:'homestead',name:'Садиба мандрівника',x:13,y:33,art:9});zones.village.roads.push({x:12,y:28,w:3,h:9});
 for(const [id,x,y]of [['runes-forest',11,26],['runes-crypt',5,24],['runes-castle',8,43]]){const d=SECRETS[id];zones[d.zone].objects.push({id,kind:'riddle',name:d.name,x,y,art:11});items[d.reward]={name:{'secret-leaf':'Лист вічної весни','secret-bell':'Дзвін загубленої кімнати','secret-crown':'Обруч забутого володаря'}[d.reward],kind:'accessory',slot:'accessory',rarity:'epic',bound:true,requirements:{level:id==='runes-castle'?30:10},stats:id==='runes-forest'?{hp:55,sp:25}:id==='runes-crypt'?{def:10,mdef:10}:{atk:18,matk:18},desc:'Унікальна особиста нагорода за розгадану таємницю.'};}
 zones.crypt.floorRooms.push({x:3,y:17,w:5,h:5});zones.crypt.objects.push({id:'secret-vault',kind:'secretVault',name:'Скриня загубленої кімнати',x:5,y:19,art:9});
 zones.forest.objects.push({id:'night-spirit',kind:'nightSpirit',name:'Дух нічної верби',x:10,y:27,art:11});
 for(const [id,e]of Object.entries(enemies)){if(['witch','thorndryad','candlewraith'].includes(id)){e.tactic='healer';e.role+=' · лікує союзника: перервіть підготовку';}if(['scarecrow','ironmole','icerevenant'].includes(id)){e.tactic='protector';e.role+=' · прикриває союзників поруч';}if(['skeleton','castleward'].includes(id)){e.tactic='skirmisher';e.role+=' · змінює позицію між пострілами';}}
}
const plots={ward:[['Сліди біля воріт','Вовки відрізали вартовим шлях додому. Звільни стежку, і ми знатимемо, що на тебе можна покластися.'],['Імена на кістках','Колишній дозор став кістяною вартою. Поверни спокій тим, чиї імена ми ще пам’ятаємо.'],['Прапор над брамою','Замкова варта служить порожньому трону. Відкрий прохід для тих, хто шукає прихистку.']],grove:[['Гіркі спори','Ліс задихається від чужої отрути. Зупини спорові осередки.'],['Терновий борг','Богомоли стережуть коріння, уражене прокляттям. Допоможи лісу відростити нові пагони.'],['Голос під корою','Дріади забули власні пісні. Звільни їх від тернового шепоту.']],forge:[['Вогонь у лусці','Перші горни зігрівав драконячий жар. Перевір свою витримку проти його хранителів.'],['Сонячне скло','Скарабеї зберігають іскри давнього сонця. Відкрий майстрам шлях до пісків.'],['Пробудити копальні','Залізні кроти руйнують старі штольні. Захисти рудну жилу — і Братство визнає тебе своїм.']]};
export const FACTION_QUESTS=Object.entries(FACTIONS).flatMap(([id,f])=>f.targets.map((target,i)=>({id:'faction-'+id+'-'+i,npc:f.npc,faction:id,reputation:[100,150,250][i],title:plots[id][i][0],text:plots[id][i][1],level:[6,18,30][i],requires:i?'faction-'+id+'-'+(i-1):null,objectives:[{type:'kill',id:target,count:[6,12,18][i]}],reward:{xp:[700,3500,9000][i],zeny:[200,500,1000][i],item:'faction-'+id+'-'+(i+1)}})));
